```swift
import SwiftUI

/// A 2:3 book cover. Set the width from outside; the height follows.
struct BookCoverView: View {
    let book: Book
    var variant: CoverVariant = .thumbnail

    @State private var loaded: (coverID: UUID, image: UIImage)?

    var body: some View {
        let cover = book.cover
        RoundedRectangle(cornerRadius: 6)
            .fill(.quaternary)
            .aspectRatio(2.0 / 3.0, contentMode: .fit)
            .overlay {
                if let image = shownImage(for: cover) {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else if cover == nil {
                    Image(systemName: "book.closed")
                        .font(variant == .full ? .largeTitle : .body)
                        .foregroundStyle(.secondary)
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: 6))
            .accessibilityHidden(true)
            .task(id: cover?.id) {
                guard let cover = book.cover else { return }
                if let image = await CoverImageCache.shared.image(for: cover, variant: variant) {
                    loaded = (cover.id, image)
                }
            }
    }

    private func shownImage(for cover: BookCover?) -> UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.coverID == cover.id { return loaded.image }
        let cache = CoverImageCache.shared
        // On the book screen, show the list thumbnail until the large image is ready.
        return cache.cachedImage(for: cover, variant: variant)
            ?? (variant == .full ? cache.cachedImage(for: cover, variant: .thumbnail) : nil)
    }
}
