## 7. `BookCoverStore.swift`: сохранение и удаление

```swift
import SwiftData
import UIKit

@MainActor
enum BookCoverStore {
    static func setCover(_ photo: UIImage, for book: Book, in context: ModelContext) async throws {
        guard let output = await CoverProcessor.process(photo) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        // The book may have been deleted while the photo was being processed.
        guard !book.isDeleted, book.modelContext != nil else { return }

        if let old = book.cover {
            context.delete(old)
        }
        book.cover = BookCover(thumbnailData: output.thumbnail, imageData: output.image)
        try context.save()
    }

    static func removeCover(from book: Book, in context: ModelContext) throws {
        guard let cover = book.cover else { return }
        book.cover = nil
        context.delete(cover)
        try context.save()
    }
}
```

