```swift
import Testing
import UIKit
@testable import Slumpy

struct CoverStoreTests {
    let directory = URL.temporaryDirectory.appending(path: UUID().uuidString, directoryHint: .isDirectory)

    @Test func savedCoverIsDownscaledAndKeepsOrientation() async throws {
        let store = CoverStore(directory: directory)
        // Как с камеры: матрица пишет 4000×3000, телефон держали вертикально.
        let id = try await store.save(makePhoto(pixelWidth: 4000, pixelHeight: 3000, orientation: .right))

        let full = try #require(await store.image(id, size: .full))
        let thumb = try #require(await store.image(id, size: .thumbnail))
        #expect(full.size == CGSize(width: 1200, height: 1600))
        #expect(thumb.size == CGSize(width: 300, height: 400))
    }

    @Test func deletedCoverIsGone() async throws {
        let store = CoverStore(directory: directory)
        let id = try await store.save(makePhoto(pixelWidth: 800, pixelHeight: 600, orientation: .up))

        await store.delete(id)

        #expect(await store.image(id, size: .full) == nil)
        #expect(await store.image(id, size: .thumbnail) == nil)
    }

    @Test func cleanupRemovesOnlyOldUnusedCovers() async throws {
        let store = CoverStore(directory: directory)
        let used = try await store.save(makePhoto(pixelWidth: 800, pixelHeight: 600, orientation: .up))
        let unused = try await store.save(makePhoto(pixelWidth: 800, pixelHeight: 600, orientation: .up))

        await store.removeOrphans(keeping: [used], now: .now)
        #expect(await store.image(unused, size: .full) != nil)

        await store.removeOrphans(keeping: [used], now: .now.addingTimeInterval(2 * 24 * 60 * 60))
        #expect(await store.image(used, size: .full) != nil)
        #expect(await store.image(used, size: .thumbnail) != nil)
        #expect(await store.image(unused, size: .full) == nil)
        #expect(await store.image(unused, size: .thumbnail) == nil)
    }

    private func makePhoto(pixelWidth: CGFloat, pixelHeight: CGFloat, orientation: UIImage.Orientation) -> UIImage {
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        let raw = UIGraphicsImageRenderer(size: CGSize(width: pixelWidth, height: pixelHeight), format: format)
            .image { context in
                UIColor.systemTeal.setFill()
                context.fill(CGRect(x: 0, y: 0, width: pixelWidth, height: pixelHeight))
            }
        return UIImage(cgImage: raw.cgImage!, scale: 1, orientation: orientation)
    }
}
```

Тест на ориентацию нужен потому, что фото с камеры хранится повёрнутым. Если уменьшение фото этот поворот потеряет, обложки лягут набок, и тест на это упадёт.

После удаления книги её файлы обложки удаляются при следующем запуске приложения, если с момента съёмки прошло больше суток.

Для следующего шага есть вариант получше: системный сканер документов (`VNDocumentCameraViewController`) сам находит края обложки и выравнивает перспективу, так что фон вокруг книги в кадр не попадёт. Сейчас я его не добавлял.

Ниже готовое решение: шесть новых файлов, одна строка в модели `Book`, одна в `Info.plist` и пара вставок в существующие экраны.

**Сборку я не проверял.** Здесь нет Xcode, поэтому код ни разу не компилировался и не запускался. Тесты из шага 9 тоже не запускались. При первой сборке ошибки возможны, их нужно будет поправить.

## Как это устроено

1. **Фото хранятся файлами на устройстве, а не в базе.** В книге хранится только короткий идентификатор обложки `coverID`. Поэтому список из 500+ книг открывается так же быстро, как без обложек, и база не разрастается.
2. **Оригинал 12 Мп не сохраняется.** Из него делаются две копии: 1600 px (около 300 КБ) для экрана книги и 400 px (около 30 КБ) для списка. Оригиналы на 500 книг заняли бы 2 ГБ и больше, а так выходит примерно 150–200 МБ.
3. **Тяжёлая работа идёт в фоне.** Уменьшение фото и чтение файлов не тормозят интерфейс. Уже показанные обложки держатся в памяти (не больше 60 МБ, система сама освобождает этот кэш при нехватке памяти), поэтому при прокрутке они не мигают.
4. **У каждой новой фотографии свой `coverID`.** После пересъёмки старая картинка не всплывёт из кэша. Старый файл удаляется только после того, как новая обложка точно сохранилась, поэтому сбой посередине не оставит книгу без обложки.
5. **Лишние файлы чистятся при запуске.** Это файлы удалённых книг, которые ни на что не ссылаются. Файлы моложе суток не трогаются. Если книг в базе нет или база не прочиталась, чистка ничего не удаляет.
6. **Файлы лежат в папке приложения Application Support.** Она попадает в обычную резервную копию iPhone в iCloud.

## Допущения

- Синхронизации библиотеки между устройствами через iCloud (CloudKit) нет. Если её включат, обложки сами между устройствами не перенесутся, для этого понадобится отдельное решение.
- Версии схемы базы (`VersionedSchema`) не используются. Новое поле необязательное, и SwiftData добавит его сама. Если версии схемы есть, нужно завести новую.
- Фото берётся только с камеры, без выбора из галереи и без ручной обрезки. В списке обложка обрезается по центру до пропорции книги 2:3, на экране книги фото показывается целиком.
- На симуляторе камеры нет, поэтому кнопка съёмки там скрыта. Удалить обложку можно и без камеры.
- Размер обложки в строке списка 44×66 pt, на экране книги — до 240×360 pt. Эти числа можно подогнать под дизайн.
- Весь код ниже кладётся в само приложение, а не в локальный пакет логики: он использует UIKit, а пакету по правилам проекта UI-фреймворки запрещены.
- Если в приложении уже есть свой экран камеры, его `UIImage` можно передавать прямо в `setCover` из шага 5, а `CameraPicker` не нужен.

