## 2. `CoverStore.swift`: хранение, уменьшение фото, кэш

```swift
import UIKit

nonisolated enum CoverSize: Sendable {
    /// Для списка библиотеки.
    case thumbnail
    /// Для экрана книги.
    case full

    var maxPixelSide: CGFloat {
        switch self {
        case .thumbnail: 400
        case .full: 1600
        }
    }

    var fileSuffix: String {
        switch self {
        case .thumbnail: "thumb"
        case .full: "full"
        }
    }
}

nonisolated enum CoverError: Error {
    case encodingFailed
}

/// Файлы обложек в Application Support/Covers: `{coverID}-full.jpg` и `{coverID}-thumb.jpg`.
/// Актор: вся работа с файлами и картинками идёт вне главного потока.
actor CoverStore {
    static let shared = CoverStore()

    private let directory: URL

    init(directory: URL = .applicationSupportDirectory.appending(path: "Covers", directoryHint: .isDirectory)) {
        self.directory = directory
    }

    /// Уменьшает фото с камеры, сохраняет две копии и возвращает новый coverID.
    func save(_ photo: UIImage) throws -> UUID {
        let (fullData, thumbData) = try autoreleasepool {
            let full = resized(photo, maxPixelSide: CoverSize.full.maxPixelSide)
            let thumb = resized(full, maxPixelSide: CoverSize.thumbnail.maxPixelSide)
            guard let fullData = full.jpegData(compressionQuality: 0.8),
                  let thumbData = thumb.jpegData(compressionQuality: 0.75)
            else { throw CoverError.encodingFailed }
            return (fullData, thumbData)
        }

        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let id = UUID()
        do {
            try fullData.write(to: fileURL(id, .full), options: .atomic)
            try thumbData.write(to: fileURL(id, .thumbnail), options: .atomic)
        } catch {
            delete(id)
            throw error
        }
        return id
    }

    /// Читает и сразу декодирует картинку, чтобы показ не тормозил прокрутку.
    func image(_ id: UUID, size: CoverSize) -> UIImage? {
        guard let image = UIImage(contentsOfFile: fileURL(id, size).path(percentEncoded: false)) else { return nil }
        return image.preparingForDisplay() ?? image
    }

    func delete(_ id: UUID) {
        for size in [CoverSize.thumbnail, .full] {
            try? FileManager.default.removeItem(at: fileURL(id, size))
        }
    }

    /// Удаляет файлы обложек, на которые не ссылается ни одна книга.
    /// Файлы моложе суток не трогает: их может прямо сейчас сохранять экран книги.
    func removeOrphans(keeping used: Set<UUID>, now: Date = .now) {
        let files = (try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.contentModificationDateKey]
        )) ?? []
        for file in files {
            guard let id = UUID(uuidString: String(file.lastPathComponent.prefix(36))),
                  !used.contains(id)
            else { continue }
            let modified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]))?
                .contentModificationDate ?? .distantPast
            guard now.timeIntervalSince(modified) > 24 * 60 * 60 else { continue }
            try? FileManager.default.removeItem(at: file)
        }
    }

    private func fileURL(_ id: UUID, _ size: CoverSize) -> URL {
        directory.appending(path: "\(id.uuidString)-\(size.fileSuffix).jpg", directoryHint: .notDirectory)
    }

    /// Уменьшает до maxPixelSide по длинной стороне (не увеличивает) и «впекает» поворот:
    /// фото с камеры хранится повёрнутым, а метка ориентации теряться не должна.
    private func resized(_ image: UIImage, maxPixelSide: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxPixelSide / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}

/// Уже показанные обложки в памяти. Система сама чистит NSCache при нехватке памяти.
@MainActor
final class CoverCache {
    static let shared = CoverCache()

    private let cache = NSCache<NSString, UIImage>()

    init() {
        cache.totalCostLimit = 60 * 1024 * 1024
    }

    func image(_ id: UUID, _ size: CoverSize) -> UIImage? {
        cache.object(forKey: key(id, size))
    }

    func insert(_ image: UIImage, _ id: UUID, _ size: CoverSize) {
        let bytes = Int(image.size.width * image.scale * image.size.height * image.scale * 4)
        cache.setObject(image, forKey: key(id, size), cost: bytes)
    }

    private func key(_ id: UUID, _ size: CoverSize) -> NSString {
        "\(id.uuidString)-\(size.fileSuffix)" as NSString
    }
}
```

## 3. `BookCoverView.swift`: показ обложки

```swift
import SwiftUI
import UIKit

struct BookCoverView: View {
    let coverID: UUID?
    var size: CoverSize = .thumbnail
    /// .fill — обрезать по рамке (список), .fit — показать фото целиком (экран книги).
    var contentMode: ContentMode = .fill

    @State private var loaded: LoadedCover?

    private struct LoadedCover {
        let id: UUID
        let image: UIImage
    }

    var body: some View {
        Group {
            if let image = displayedImage {
                if contentMode == .fill {
                    Color.clear
                        .overlay { Image(uiImage: image).resizable().scaledToFill() }
                        .clipped()
                } else {
                    Image(uiImage: image).resizable().scaledToFit()
                }
            } else {
                CoverPlaceholder()
            }
        }
        .task(id: coverID) { await load() }
    }

    private var displayedImage: UIImage? {
        guard let coverID else { return nil }
        if let loaded, loaded.id == coverID { return loaded.image }
        // Пока грузится большая картинка, показываем миниатюру из списка, если она уже есть.
        return CoverCache.shared.image(coverID, size) ?? CoverCache.shared.image(coverID, .thumbnail)
    }

    private func load() async {
        guard let coverID, loaded?.id != coverID else { return }
        if let cached = CoverCache.shared.image(coverID, size) {
            loaded = LoadedCover(id: coverID, image: cached)
            return
        }
        guard let image = await CoverStore.shared.image(coverID, size: size), !Task.isCancelled else { return }
        CoverCache.shared.insert(image, coverID, size)
        loaded = LoadedCover(id: coverID, image: image)
    }
}

struct CoverPlaceholder: View {
    var body: some View {
        ZStack {
            Rectangle().fill(.quaternary)
            Image(systemName: "book.closed")
                .foregroundStyle(.secondary)
        }
    }
}
