            cover
            actions.disabled(isSaving)
        }
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                Task { await setCover(photo) }
            }
            .ignoresSafeArea()
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) {
                Task { await removeCover() }
            }
        }
        .alert("Нет доступа к камере", isPresented: $isCameraAccessAlertPresented) {
            Button("Открыть настройки") {
