            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы сфотографировать обложку.")
        }
        .alert(
            "Не получилось",
            isPresented: Binding(get: { errorMessage != nil }, set: { if !$0 { errorMessage = nil } })
        ) {
            Button("OK", role: .cancel) {}
        } message: {
            Text(errorMessage ?? "")
        }
    }

    private var cover: some View {
        ZStack {
            if book.coverID == nil {
                CoverPlaceholder()
                    .frame(width: 160, height: 240)
                    .clipShape(.rect(cornerRadius: 8))
            } else {
                BookCoverView(coverID: book.coverID, size: .full, contentMode: .fit)
                    .clipShape(.rect(cornerRadius: 8))
                    .frame(maxWidth: 240, maxHeight: 360)
            }
            if isSaving {
                ProgressView().controlSize(.large)
            }
        }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(book.coverID == nil ? "Обложки нет" : "Обложка книги «\(book.title)»")
    }

    @ViewBuilder
    private var actions: some View {
        HStack(spacing: 16) {
            if isCameraAvailable {
                Button(book.coverID == nil ? "Сфотографировать обложку" : "Переснять", systemImage: "camera") {
                    Task { await openCamera() }
                }
            }
            if book.coverID != nil {
                Button("Удалить", systemImage: "trash", role: .destructive) {
                    isConfirmingRemoval = true
                }
            }
        }
    }

    private func openCamera() async {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            isCameraPresented = true
        case .notDetermined:
            if await AVCaptureDevice.requestAccess(for: .video) {
                isCameraPresented = true
            } else {
                isCameraAccessAlertPresented = true
            }
        default:
            isCameraAccessAlertPresented = true
        }
    }

    /// Порядок важен: сначала файлы, потом запись в базе, и только потом удаление старых файлов.
    private func setCover(_ photo: UIImage) async {
        isSaving = true
        defer { isSaving = false }
        let oldID = book.coverID
        do {
            let newID = try await CoverStore.shared.save(photo)
            book.coverID = newID
            do {
                try modelContext.save()
            } catch {
                book.coverID = oldID
                await CoverStore.shared.delete(newID)
                throw error
            }
            if let oldID { await CoverStore.shared.delete(oldID) }
        } catch {
            errorMessage = "Не удалось сохранить обложку. Попробуйте ещё раз."
        }
    }

    private func removeCover() async {
        guard let oldID = book.coverID else { return }
        book.coverID = nil
        do {
            try modelContext.save()
            await CoverStore.shared.delete(oldID)
        } catch {
            book.coverID = oldID
            errorMessage = "Не удалось удалить обложку. Попробуйте ещё раз."
        }
    }
}
```

## 6. `OrphanCoverCleanup.swift`: чистка при запуске

```swift
import SwiftData
import SwiftUI

/// Удаляет файлы обложек удалённых книг. Подключается один раз к корневому экрану.
struct OrphanCoverCleanup: ViewModifier {
    @Environment(\.modelContext) private var modelContext

    func body(content: Content) -> some View {
        content.task {
            var descriptor = FetchDescriptor<Book>()
            descriptor.propertiesToFetch = [\.coverID]
            // Если база не прочиталась или пуста, ничего не удаляем: лучше лишний файл, чем потерянная обложка.
            guard let books = try? modelContext.fetch(descriptor), !books.isEmpty else { return }
            await CoverStore.shared.removeOrphans(keeping: Set(books.compactMap(\.coverID)))
        }
    }
}

extension View {
    func removingOrphanCovers() -> some View {
        modifier(OrphanCoverCleanup())
    }
}
```

Подключение в файле приложения (там, где уже есть `.modelContainer`):

```swift
WindowGroup {
    RootView()            // ваш корневой экран
        .removingOrphanCovers()
}
.modelContainer(for: Book.self)
```

